import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at=name=>fileURLToPath(new URL(name,import.meta.url));
const lookup='_M0FP210JingLan0v03stn12lookup__name';
const append='_M0FP210JingLan0v03stn19append__order__rule';
for(const driver of ['lookupbench','deepbench']){
 const js=readFileSync(at('base-'+driver+'.js'),'utf8').replaceAll('\r\n','\n');
 const atStart=js.indexOf('function '+append+'(');
 const end=js.indexOf('\nfunction ',atStart+1);
 const current=js.slice(atStart,end);
 const calls=new RegExp(lookup+'\\(index, (finish_name|start_name)\\)','g');
 assert(atStart>=0&&end>atStart);
 assert.equal([...current.matchAll(calls)].length,2);
 for(const mode of ['counts','lookup','timer-control']){
  const header="const probe={lookups:0,firstLookups:0,plans:0,ms:0};\nconst visited=new WeakMap();\n"+
   'function measure(index,name){\n'+(mode==='counts'?
    '  probe.lookups++;\n  let keys=visited.get(index);\n  if(!keys){keys=new Set();visited.set(index,keys);probe.plans++}\n'+
    '  if(!keys.has(name)){probe.firstLookups++;keys.add(name)}\n  return '+lookup+'(index,name);\n':
    mode==='lookup'?'  const t=performance.now();\n  const result='+lookup+'(index,name);\n  probe.ms+=performance.now()-t;\n  return result;\n':
    '  const t=performance.now();\n  probe.ms+=performance.now()-t;\n  return '+lookup+'(index,name);\n')+
   "}\nprocess.once('exit',()=>console.error(JSON.stringify(probe)));\n";
  writeFileSync(at('base-'+driver+'-'+mode+'.js'),header+js.slice(0,atStart)+current.replace(calls,'measure(index, $1)')+js.slice(end));
 }
}
const results=[];
for(const name of ['independent','maintenance','first-pair','moved-pair','four-resources','one-resource','max-model','tight-impossible']){
 const deep=name==='tight-impossible';
 const run=mode=>{
  const args=[at('base-'+(deep?'deepbench':'lookupbench')+'-'+mode+'.js'),...(deep?[]:[name])];
  const r=spawnSync(process.execPath,args,{encoding:'utf8',timeout:40000});
  assert.ifError(r.error);
  assert.equal(r.status,0,r.stderr);
  assert.equal(r.stdout.trim().split(/\r?\n/).length,9);
  return JSON.parse(r.stderr);
 };
 const {ms,...counts}=run('counts');
 const phase={lookup:[],'timer-control':[]};
 for(let i=0;i<3;i++)for(const mode of i%2?Object.keys(phase).reverse():Object.keys(phase))phase[mode].push(run(mode).ms);
 assert(counts.firstLookups<=counts.lookups && counts.lookups%2===0);
 results.push({name,counts,ms:phase});
 console.log(name,counts.lookups,counts.firstLookups,JSON.stringify(phase));
}
writeFileSync(at('baseline-probe.json'),JSON.stringify(results,null,2)+'\n');

