import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at=f=>fileURLToPath(new URL(f,import.meta.url));
const expected=JSON.parse(readFileSync(at('baseline-probe.json'),'utf8'));
const fn='_M0FP210JingLan0v03stn24resolve__order__endpoint';
const lookup='_M0FP210JingLan0v03stn12lookup__name(index, name)';
const results={};
for(const v of ['lazy','position']){
 const rows={};
 for(const driver of ['lookupbench','deepbench']){
  const js=readFileSync(at(v+'-'+driver+'.js'),'utf8').replaceAll('\r\n','\n');
  const start=js.indexOf('function '+fn+'('), end=js.indexOf('\nfunction ',start+1);
  assert(start>=0&&end>start);
  const old=js.slice(start,end);
  assert.equal(old.split(lookup).length,2);
  const firstLine=old.indexOf('\n');
  assert(firstLine>=0);
  const updated=old.slice(0,firstLine)+
    '\n  probe.endpoints++;'+old.slice(firstLine).replace(lookup,'(probe.mapLookups++, '+lookup+')');
  const out=at(v+'-'+driver+'-counts.js');
  writeFileSync(out,"const probe={endpoints:0,mapLookups:0};\nprocess.once('exit',()=>console.error(JSON.stringify(probe)));\n"+
   js.slice(0,start)+updated+js.slice(end));
  for(const row of expected.filter(r=>(r.name==='tight-impossible')===(driver==='deepbench'))){
   const r=spawnSync(process.execPath,[out,...(driver==='deepbench'?[]:[row.name])],{encoding:'utf8',timeout:35000});
   assert.ifError(r.error);
   assert.equal(r.status,0,r.stderr);
   assert.equal(r.stdout.trim().split(/\r?\n/).length,9);
   const counts=JSON.parse(r.stderr);
   assert.equal(counts.endpoints,row.counts.lookups);
   assert.equal(counts.mapLookups,v==='lazy'?row.counts.firstLookups:row.name==='moved-pair'?row.counts.lookups:0);
   rows[row.name]=counts;
  }
 }
 results[v]=rows;
 console.log(v,JSON.stringify(Object.fromEntries(['max-model','tight-impossible','moved-pair'].map(n=>[n,rows[n]]))));
}
writeFileSync(at('variant-counts.json'),JSON.stringify(results,null,2)+'\n');

